const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Polygon(
      [[[141.69668470557286, -32.22272260662762],
        [142.1030462778385, -32.221538743120196],
        [142.1023799863346, -32.53174950275817],
        [141.6973510950664, -32.53234143492582]]]);

  const date1_start = '2017-01-20';
  const date1_end = '2017-02-05'; // Centered around Jan 27, 2017

  const date2_start = '2019-01-26';
  const date2_end = '2019-02-10'; // Centered around Feb 2, 2019

  const scale = 30; // Sentinel-2 resolution is 10m, but 30m is safer for area calculation to avoid memory errors.
  const waterThreshold = 0.05; // NDWI threshold for water

  // Function to mask clouds in Sentinel-2 images
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
        .select(['B2', 'B3', 'B4', 'B8', 'B11', 'B12'], ['Blue', 'Green', 'Red', 'NIR', 'SWIR1', 'SWIR2'])
        .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDWI
  function calculateNDWI(image) {
    const ndwi = image.normalizedDifference(['Green', 'NIR']).rename('NDWI');
    return image.addBands(ndwi);
  }

  // Function to get the least cloudy image and calculate water area
  async function getWaterArea(startDate, endDate, geometry, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .map(maskS2clouds)
        .map(calculateNDWI);

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${periodName} (Date: ${startDate} to ${endDate}).`);
      return { area: null, cloud_perc: null, img_count: 0 };
    }

    // Sort by cloud percentage and pick the least cloudy image
    const image = collection.sort('CLOUD_COVERAGE_ASSESSMENT').first();
    const cloud_perc = image.get('CLOUD_COVERAGE_ASSESSMENT').getInfo();

    // Mask water
    const water = image.select('NDWI').gt(waterThreshold);

    // Calculate valid pixels after NDWI and cloud mask
    const totalValidPixels = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    if (totalValidPixels === 0) {
      console.log(`No valid pixels after masking for ${periodName}.`);
      return { area: null, cloud_perc: cloud_perc, img_count: collectionSize };
    }

    // Calculate water area
    const waterArea = water.multiply(ee.Image.pixelArea()).divide(1e6); // Area in km^2
    const stats = await waterArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const area_km2 = stats['NDWI'];

    return { area: area_km2, cloud_perc: cloud_perc, img_count: collectionSize };
  }

  console.log("Starting Lake Menindee analysis...");

  // Get water area for period 1
  const result1 = await getWaterArea(date1_start, date1_end, lakeMenindee, "Period 1 (2017)");
  if (result1.area === null && result1.img_count === 0) {
    console.log("C1: Empty Collection (No images found for 2017).");
    console.log("C1");
    return;
  }
  if (result1.area === null && result1.img_count > 0) {
    console.log("C2: No Valid Pixels (2017 images exist, but 0 pixels remain after processing).");
    console.log("C2");
    return;
  }
  if (result1.area === undefined || isNaN(result1.area)) {
    console.log("C3: Calculation Failure (2017 area is invalid).");
    console.log("C3");
    return;
  }

  // Get water area for period 2
  const result2 = await getWaterArea(date2_start, date2_end, lakeMenindee, "Period 2 (2019)");
  if (result2.area === null && result2.img_count === 0) {
    console.log("C1: Empty Collection (No images found for 2019).");
    console.log("C1");
    return;
  }
  if (result2.area === null && result2.img_count > 0) {
    console.log("C2: No Valid Pixels (2019 images exist, but 0 pixels remain after processing).");
    console.log("C2");
    return;
  }
  if (result2.area === undefined || isNaN(result2.area)) {
    console.log("C3: Calculation Failure (2019 area is invalid).");
    console.log("C3");
    return;
  }

  const area1 = result1.area;
  const area2 = result2.area;

  console.log(`2017 Images: ${result1.img_count}, Cloud %: ${result1.cloud_perc !== null ? result1.cloud_perc.toFixed(2) : 'N/A'}`);
  console.log(`2017 Water Area: ${area1.toFixed(2)} km^2`);
  console.log(`2019 Images: ${result2.img_count}, Cloud %: ${result2.cloud_perc !== null ? result2.cloud_perc.toFixed(2) : 'N/A'}`);
  console.log(`2019 Water Area: ${area2.toFixed(2)} km^2`);

  // Compare areas
  if (area2 < area1) {
    console.log("A"); // Lake shrank
  } else {
    console.log("B"); // Lake did not shrink or grew
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
